'use strict';
const $=id=>document.getElementById(id);
const seeds={
rome:{id:'rome',title:'ローマ',roman:'Roma',crumb:'ヨーロッパ / イタリア / 都市',subtitle:'幾重もの時代が息づく、永遠の都。',lat:41.9028,lon:12.4964,overview:'ローマはイタリアの首都です。古代の遺跡と、教会、広場、宮殿が折り重なり、歩くことで時代の移り変わりを感じられます。歴史地区はユネスコの世界遺産に登録されています。',intro:'古代ローマから、キリスト教の中心地へ。ローマの街並みには、およそ3,000年にわたる歴史の層が残されています。',events:[['紀元前753年（伝承）','建国の物語','ロムルスとレムスにまつわる建国伝説があります。この年は伝承上の年代であり、考古学的に確定した建国日ではありません。'],['古代','共和国、そして帝国の中心へ','ローマは共和国、続いてローマ帝国の中心となりました。コロッセオやフォロ・ロマーノなどに、その時代の足跡を見ることができます。'],['4世紀以降','キリスト教の中心地に','キリスト教世界の中心としての役割を担い、その後のルネサンスやバロックの時代にも、教会や広場が街を彩りました。'],['1871年','イタリアの首都に','イタリア王国の首都となりました。古代からの記憶を抱きながら、近代国家の首都として歩みはじめます。']],sources:[['UNESCO｜ローマ歴史地区','https://whc.unesco.org/en/list/91/'],['イタリア政府｜ローマ首都宣言150周年','https://anniversarinazionali.governo.it/it/comunicazione/notizie/150-anni-della-proclamazione-di-roma-capitale-ditalia/'],['ローマ公式観光局｜The City','https://www.turismoroma.it/en/page/city']],note:'公開資料をもとに作成した短い概説です。資料確認：2026年11月6日。'},
nagano:{id:'nagano',title:'長野市',roman:'Nagano',crumb:'日本 / 長野県 / 市',subtitle:'善光寺の門前から広がったまち。',lat:36.6486,lon:138.1948,overview:'長野市は長野県の県庁所在地です。善光寺の門前町や松代の城下町など、さまざまな土地の歩みが重なっています。',intro:'寺を訪れる人々が行き交った門前町と、城を中心に発展した松代。長野市には、異なる成り立ちの歴史が残ります。',events:[['江戸時代','門前町と城下町の発展','善光寺門前町や松代城下町を中心に発展しました。'],['1897年','長野市の誕生','市制を施行し、長野市が誕生しました。'],['1998年','世界とつながる冬の祭典','冬季オリンピックとパラリンピックが開催されました。']],sources:[['長野市｜文化財の紹介','https://www.city.nagano.nagano.jp/n151100/contents/p002905.html'],['長野市デジタルミュージアム｜文化財について','https://adeac.jp/nagano-city/top/02about/about_bunkazai.html']],note:'長野市の公開資料をもとに作成。資料確認：2026年11月6日。'}
};
let current=seeds.rome,operation=0;
function readStore(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let saved=readStore('machi-bookmarks',[]);if(!Array.isArray(saved))saved=[];
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{$('status').textContent='このブラウザでは保存できません。閲覧と検索は引き続き使えます。';return false}}
function el(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function setStatus(text){$('status').textContent=text}
function mapLocation(p){const hasCoordinates=Number.isFinite(p.lat)&&Number.isFinite(p.lon)&&Math.abs(p.lat)<=90&&Math.abs(p.lon)<=180;return {hasCoordinates,target:hasCoordinates?p.lat+','+p.lon:p.title}}
async function api(params,endpoint='https://ja.wikipedia.org/w/api.php'){const u=new URL(endpoint);u.search=new URLSearchParams({origin:'*',format:'json',formatversion:'2',...params});const c=new AbortController(),timer=setTimeout(()=>c.abort(),14000);try{const r=await fetch(u,{signal:c.signal});if(!r.ok)throw new Error('通信エラー');const j=await r.json();if(j.error)throw new Error('資料を取得できません');return j}finally{clearTimeout(timer)}}
function resetTabs(){setTab('history')}
function setTab(name){for(const n of ['history','overview']){$(n+'Tab').setAttribute('aria-selected',String(n===name));$(n+'Tab').tabIndex=n===name?0:-1;$(n+'Content').hidden=n!==name}}
function showPlace(p){current=p;$('place').hidden=false;$('results').hidden=true;$('placeTitle').replaceChildren(document.createTextNode(p.title+' '));if(p.roman)$('placeTitle').append(el('span',p.roman));$('breadcrumb').textContent=p.crumb||'世界の国と都市 / 地域の資料';$('subtitle').textContent=p.subtitle||'歴史と地図から、この土地を知る。';
const history=$('historyContent');history.replaceChildren();history.append(el('h3','この土地の歩み'));if(p.intro)history.append(el('p',p.intro,'intro'));
if(p.events){const tl=el('div',undefined,'timeline');for(const [year,title,text]of p.events){const item=el('div',undefined,'event');item.append(el('time',year),el('h4',title),el('p',text));tl.append(item)}history.append(tl)}else if(p.history?.length){for(const t of p.history)history.append(el('p',t));history.append(el('p','続きと詳しい注釈は、下の参照資料から確認できます。','quiet'))}else history.append(el('p','この項目では歴史の節を取得できませんでした。「土地のあらまし」と、下の参照資料をご覧ください。'));
$('overviewContent').replaceChildren(el('h3','土地のあらまし'),el('p',p.overview||'概要が見つかりません。参照資料をご確認ください。'));
$('sources').replaceChildren();for(const [label,url]of p.sources||[]){const a=el('a',label+' ↗');a.href=url;a.target='_blank';a.rel='noopener noreferrer';$('sources').append(a)}$('sourceNote').textContent=p.note||'Wikipediaの本文を抜粋表示しています。編集者による記述で、必ずしも確定した事実とは限りません。原文・編集履歴・参考文献をご確認ください。本文のライセンス：CC BY-SA。';
const location=mapLocation(p);$('googleLink').href='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(location.target);$('routeLink').href='https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(location.target);
$('googleLink').textContent=location.hasCoordinates?'Googleマップで開く ↗':'Googleマップで地名を検索 ↗';$('routeLink').textContent=location.hasCoordinates?'ここへの行き方を調べる ↗':'この地名への行き方を検索 ↗';$('googleLink').setAttribute('aria-label',p.title+(location.hasCoordinates?'の代表地点をGoogleマップで開く':'をGoogleマップで検索'));$('routeLink').setAttribute('aria-label',p.title+(location.hasCoordinates?'の代表地点への行き方を調べる':'への行き方を地名で検索'));
$('mapLabel').textContent=p.title+'の代表地点付近';const frame=$('mapFrame');frame.title=p.title+'の代表地点付近の地図';if(location.hasCoordinates){frame.src='/map.html?lat='+p.lat+'&lon='+p.lon+'&zoom='+(p.country?4:12);frame.hidden=false}else{frame.removeAttribute('src');frame.hidden=true;$('mapLabel').textContent='座標の登録がありません';}let fallback=document.querySelector('.mapfallback');if(!fallback){fallback=el('p','この項目には位置座標がありません。下のGoogleマップのボタンから地名を検索できます。同名の場所がある場合は、国や地域を確認して選んでください。','mapfallback quiet');fallback.style.padding='32px';document.querySelector('.maparea').append(fallback)}fallback.hidden=!frame.hidden;
resetTabs();updateSaveButton();renderSaved();document.title=p.title+'の歴史と地図｜まちの記憶';}
function updateSaveButton(){const yes=saved.some(p=>p.id===current.id);$('saveButton').textContent=yes?'★ 保存済み':'☆ お気に入り';$('saveButton').setAttribute('aria-pressed',String(yes))}
function renderSaved(){$('savedPlaces').replaceChildren();if(!saved.length){$('savedPlaces').append(el('p','気になる土地を「☆ お気に入り」に入れて、また訪ねましょう。','quiet'));return}for(const p of saved){const b=el('button',p.title+' →','bookmark');b.onclick=()=>{operation++;$('searchButton').disabled=false;setStatus('');showPlace(p);$('place').scrollIntoView({behavior:'smooth',block:'start'})};$('savedPlaces').append(b)}}
async function search(query){query=query.trim();if(!query)return;const op=++operation;$('searchInput').value=query;$('results').hidden=true;setStatus('「'+query+'」の候補を探しています…');$('searchButton').disabled=true;try{const data=await api({action:'query',list:'search',srsearch:query,srlimit:'8',srnamespace:'0',srprop:'snippet'});if(op!==operation)return;const list=data.query?.search||[];if(!list.length){setStatus('候補が見つかりませんでした。別の地名や、日本語の表記でお試しください。');return}setStatus('');$('candidates').replaceChildren();for(const item of list){const b=el('button',undefined,'candidate');const text=new DOMParser().parseFromString(item.snippet,'text/html').body.textContent;b.append(el('strong',item.title+' →'),el('small',text||'この項目を開く'));b.onclick=()=>loadPlace(item.title);$('candidates').append(b)}$('results').hidden=false;$('results').scrollIntoView({behavior:'smooth',block:'nearest'})}catch{if(op===operation){setStatus('検索サービスに接続できませんでした。通信環境を確認して、もう一度「探す」を押してください。ローマと長野市の紹介は引き続き使えます。')}}finally{if(op===operation)$('searchButton').disabled=false}}
async function loadPlace(title){if(title==='ローマ'){operation++;showPlace(seeds.rome);setStatus('');$('searchButton').disabled=false;return}if(title==='長野市'){operation++;showPlace(seeds.nagano);setStatus('');$('searchButton').disabled=false;return}const op=++operation;setStatus('「'+title+'」の資料を読み込んでいます…');$('searchButton').disabled=true;try{const data=await api({action:'query',titles:title,redirects:'1',prop:'extracts|coordinates|pageprops|pageterms',exintro:'1',explaintext:'1',colimit:'1',coprimary:'primary',wbptterms:'description'});const page=data.query?.pages?.[0];if(!page||page.missing)throw new Error('not found');let history=[],sections;try{sections=await api({action:'parse',page:page.title,prop:'sections'});const section=sections.parse?.sections?.find(s=>/^(歴史|沿革|歴史・沿革|歴史と沿革|歴史・地理)$/.test(s.line.replace(/<[^>]*>/g,'')))||sections.parse?.sections?.find(s=>/歴史|沿革/.test(s.line));if(section){const h=await api({action:'parse',page:page.title,prop:'text',section:section.index,disableeditsection:'1'});const doc=new DOMParser().parseFromString(h.parse.text,'text/html');doc.querySelectorAll('table,sup,style,script,.mw-empty-elt,.hatnote,.navbox,.thumb,.metadata').forEach(n=>n.remove());history=[...doc.querySelectorAll('p')].map(n=>n.textContent.trim()).filter(t=>t.length>25).slice(0,12)}}catch{/* Overview remains usable when a history section is unavailable. */}if(op!==operation)return;let co=page.coordinates?.[0];if(!co&&page.pageprops?.wikibase_item){try{const wd=await api({action:'wbgetclaims',entity:page.pageprops.wikibase_item,property:'P625'},'https://www.wikidata.org/w/api.php');const claims=wd.claims?.P625||[];const claim=claims.find(c=>c.rank==='preferred')||claims.find(c=>c.rank!=='deprecated');const v=claim?.mainsnak?.datavalue?.value;if(v?.globe==='http://www.wikidata.org/entity/Q2')co={lat:v.latitude,lon:v.longitude}}catch{}}if(op!==operation)return;const description=page.terms?.description?.[0]||'';const p={id:'wiki:'+page.pageid,title:page.title,subtitle:description,overview:page.extract,history,lat:co?.lat,lon:co?.lon,country:/国家|共和国|王国|の国$|位置する国|所在する国/.test(description),sources:[['Wikipedia｜'+page.title,'https://ja.wikipedia.org/?curid='+page.pageid],['本文の利用条件（CC BY-SA）','https://creativecommons.org/licenses/by-sa/4.0/deed.ja']],note:'Wikipediaの本文を抜粋。取得日：'+new Date().toLocaleDateString('ja-JP')+'。履歴と参考文献は元記事で確認できます。地図は記事の代表座標で、領域や国境を示すものではありません。'};showPlace(p);setStatus(history.length?'':'歴史の節を取得できませんでした。「土地のあらまし」と元の記事をご覧ください。');$('place').scrollIntoView({behavior:'smooth',block:'start'})}catch{if(op===operation)setStatus('資料を取得できませんでした。候補を選び直すか、時間をおいてお試しください。')}finally{if(op===operation)$('searchButton').disabled=false}}
$('searchForm').addEventListener('submit',e=>{e.preventDefault();search($('searchInput').value)});document.querySelectorAll('[data-search]').forEach(b=>b.onclick=()=>search(b.dataset.search));document.querySelectorAll('[data-local]').forEach(b=>b.onclick=()=>{operation++;setStatus('');$('searchButton').disabled=false;showPlace(seeds[b.dataset.local])});$('historyTab').onclick=()=>setTab('history');$('overviewTab').onclick=()=>setTab('overview');for(const name of ['history','overview'])$(name+'Tab').onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const next=name==='history'?'overview':'history';setTab(next);$(next+'Tab').focus()}};
$('saveButton').onclick=()=>{const next=saved.some(p=>p.id===current.id)?saved.filter(p=>p.id!==current.id):[...saved,current];if(persist('machi-bookmarks',next)){saved=next;updateSaveButton();renderSaved()}};
function setFont(on){document.body.classList.toggle('large',on);$('fontButton').textContent=on?'文字を標準に':'文字を大きく';$('fontButton').setAttribute('aria-pressed',String(on))}setFont(readStore('machi-large',false));$('fontButton').onclick=()=>{const on=!document.body.classList.contains('large');setFont(on);persist('machi-large',on)};$('helpButton').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();$('helpDialog').onclick=e=>{if(e.target===$('helpDialog'))$('helpDialog').close()};showPlace(seeds.rome);
